import Redis from "ioredis";
import { latestCached } from "@/lib/latestCached";

// Single Redis client reused across warm invocations.
// maxRetriesPerRequest: 1 prevents long hangs on connection failure in serverless.
const redis = process.env.REDIS_URL
  ? new Redis(process.env.REDIS_URL, { maxRetriesPerRequest: 1, lazyConnect: true })
  : null;

export const dynamic = "force-dynamic";

// The analysis itself is generated by the separate stockBot_AI_Insight worker
// (Claude Code CLI, subscription-billed, run on its own cron schedule) and written
// to Redis. This route never calls Claude — it only reads whatever the worker has
// already produced for today.
export async function GET() {
  if (!redis) {
    return Response.json(
      { error: "REDIS_URL not configured — add it to .env.local or Vercel Environment Variables." },
      { status: 503 }
    );
  }

  try {
    const result = await latestCached(
      redis,
      (date) => [`ai-analysis:${date}`],
      (date) => `ai-analysis-prompt:${date}`,
    );
    if (!result) {
      return Response.json({ error: "No analysis found in the last few days." }, { status: 404 });
    }

    return Response.json(result);
  } catch (err) {
    return Response.json(
      { error: err instanceof Error ? err.message : String(err) },
      { status: 500 }
    );
  }
}
